package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import vn.tuan.entity.*;import vn.tuan.repository.*;import java.util.*;import java.math.*;
@Service @RequiredArgsConstructor public class CatalogService {
 private final ProductRepository products;
 public Page<Product> search(String keyword,Integer categoryId,Integer shopId,String sort,boolean guest,int page){Specification<Product> spec=(root,q,cb)->{var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();predicates.add(cb.equal(root.get("status"),"ACTIVE"));predicates.add(cb.equal(root.get("shop").get("status"),"ACTIVE"));if(keyword!=null && !keyword.isBlank())predicates.add(cb.like(cb.lower(root.get("name")),"%"+keyword.trim().toLowerCase(Locale.ROOT)+"%"));if(categoryId!=null)predicates.add(cb.equal(root.get("category").get("id"),categoryId));if(shopId!=null)predicates.add(cb.equal(root.get("shop").get("id"),shopId));if(guest && (keyword==null || keyword.isBlank()) && categoryId==null && shopId==null)predicates.add(cb.gt(root.get("soldCount"),10));
 if(!Long.class.equals(q.getResultType())){if("rating".equals(sort)){var sub=q.subquery(Double.class);var r=sub.from(Review.class);sub.select(cb.avg(r.get("rating"))).where(cb.equal(r.get("product"),root));q.orderBy(cb.desc(cb.coalesce(sub,0.0)),cb.desc(root.get("id")));}else if("favorite".equals(sort)){var sub=q.subquery(Long.class);var r=sub.from(ProductActivity.class);sub.select(cb.count(r)).where(cb.equal(r.get("product"),root),cb.isTrue(r.get("favorite")));q.orderBy(cb.desc(sub),cb.desc(root.get("id")));}else q.orderBy(cb.desc(root.get(guest || "sold".equals(sort)?"soldCount":"createdAt")),cb.desc(root.get("id")));}return cb.and(predicates.toArray(new jakarta.persistence.criteria.Predicate[0]));};return products.findAll(spec,PageRequest.of(Math.max(0,page),20));}
}
